import React, { useState, useEffect, useRef } from "react";
import "./ChatBox.css";

const ChatBox = () => {
  const [isOpen, setIsOpen] = useState(false);         // To toggle chat window
  const [messages, setMessages] = useState([]);        // Conversation history
  const [input, setInput] = useState("");               // Input message

  const messagesEndRef = useRef(null);

  // Scroll chat to bottom when new message arrives
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages]);

  // Simulate AI response (replace with real API call)
  const getAIResponse = (userMessage) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(`You said: "${userMessage}". This is a simulated AI response.`);
      }, 1000);
    });
  };

  const handleSend = async () => {
    if (!input.trim()) return;

    // Add user message
    setMessages((msgs) => [...msgs, { sender: "user", text: input }]);
    setInput("");

    // Get AI response
    const response = await getAIResponse(input);

    // Add AI message
    setMessages((msgs) => [...msgs, { sender: "ai", text: response }]);
  };

  // Send message on Enter key
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button
        className="chat-toggle-btn"
        onClick={() => setIsOpen(!isOpen)}
        aria-label={isOpen ? "Close chat" : "Open chat"}
      >
        {isOpen ? "✖" : "💬"}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="chat-window">
          <div className="chat-header">CampusMarket AI Chat</div>

          <div className="chat-messages">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`chat-message ${
                  msg.sender === "user" ? "user-message" : "ai-message"
                }`}
              >
                {msg.text}
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>

          <div className="chat-input-area">
            <textarea
              rows="2"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Type your message..."
            />
            <button onClick={handleSend} aria-label="Send message">
              Send
            </button>
          </div>
        </div>
      )}
    </>
  );
};

export default ChatBox;
